// Left front: is the KPD in the driver's seat? (same scoring as ending_slides)
Q.era2_vanguard = 0;
if (Q.era2_path == "left") {
    var eff_unemployed = Math.max(0, Q.unemployed - (Q.workers_aid * Q.workers_aid_support || 0));
    var pts = (Q.rfb_force || 0) + (100 - Q.pro_republic) / 2 + eff_unemployed / 2 + Q.kpd_votes + (Q.soviet_relation || 0);
    if (Q.president == "Thälmann") pts += 16;
    if (Q.president == "Münzenberg") pts += 10;
    if (Q.kpd_leader == "Conciliators") pts += 6;
    if (Q.sapd_formed) pts += 2 + (Q.sapd_votes || 0);
    if (Q.spd_votes < 26) pts += 5;
    if (Q.eu) pts -= 10;
    if (Q.spd_votes >= 36) pts -= 5;
    if (Q.spd_votes >= 40) pts -= 5;
    Q.era2_vanguard = pts >= 50 ? 1 : 0;
}

// The Republic won the war: whoever held the chancellery when it began, the government that
// comes out of it is led by the SPD (sdx_* audit fix; otherwise Papen or Hitler stayed Chancellor).
if ((Q.era2_path == "civil_war" || Q.era2_path == "divided") && (Q.chancellor_party != "SPD" || !Q.spd_in_government)) {
    Q.spd_in_government = 1;
    Q.chancellor_party = "SPD";
