}

// The civil war was won (sdx_*): outright, or after foreign aid turned a long war (sdx_long_war_won).
// Runs before e2_stability and e2_west are derived, so both reflect it.
if (Q.era2_path == "civil_war") {
    var sdxClasses = ["workers", "old_middle", "new_middle", "rural", "catholics", "unemployed"];
    var sdxMove = function (from, to, share) {
        sdxClasses.forEach(function (c) {
            var amt = (Q[c + "_" + from] || 0) * share;
            Q[c + "_" + from] -= amt;
            if (to) Q[c + "_" + to] = (Q[c + "_" + to] || 0) + amt;
        });
    };
    // The far right was beaten in the field: it loses two thirds of its support.
    // With Western aid, a third of what the NSDAP loses goes to a red-brown KPD instead.
    sdxMove("nsdap", Q.sdx_long_war_won && Q.west_aid ? "kpd" : 0, Q.sdx_long_war_won && Q.west_aid ? 0.22 : 0);
    sdxMove("nsdap", 0, Q.sdx_long_war_won && Q.west_aid ? 0.43 / 0.78 : 0.65);
    sdxMove("dnvp", 0, 0.65);
    Q.nationalism = Math.max(0, Q.nationalism - 15);
    if (!Q.sdx_long_war_won) {
        Q.pro_republic = 100;
    } else {
        Q.pro_republic += 10;
        if (Q.soviet_aid) {
            // Moscow armed the Red Front: the KPD takes a tenth of the governing parties' support.
            Q.socialism += 20;
            Q.nationalism += 5;
            Q.soviet_relation += 2;
            Q.west_relation -= 2;
            sdxMove("spd", "kpd", 0.1); sdxMove("z", "kpd", 0.1); sdxMove("ddp", "kpd", 0.1);
            if (Q.sdx_kpd_moscow < 50 || Q.kpd_leader == "Conciliators") Q.pro_republic += 10;
            else Q.pro_republic -= 15;
        }
        if (Q.west_aid) {
            // Saved by the Versailles powers: the KPD turns red-brown under Thälmann.
            Q.pro_republic += 15;
            Q.west_relation = 6;
            Q.kpd_relation -= 25;
            Q.soviet_relation -= 3;
            Q.sdx_kpd_moscow = 100 - (100 - Q.sdx_kpd_moscow) * 0.25;
            Q.kpd_leader = "Thälmann";
            Q.kpd_chair = 0;
            Q.sdx_kpd_line = "red_brown";
        }
        if (Q.east_aid) {
            // Polish and Czechoslovak troops on German soil: a gift to every nationalist.
            Q.nationalism += 25;
            Q.pro_republic -= 20;
            Q.east_relation += 2;
            Q.reichswehr_strength = Math.round(Q.reichswehr_strength * 0.75);
            Q.reichswehr_loyalty = Math.max(0, Q.reichswehr_loyalty - 0.2);
            Q.e2c_new_right = (Q.e2c_new_right || 0) + 8;
            Q.sdx_east_coup = 10;
        }
    }
    Q.pro_republic = Math.max(0, Math.min(100, Q.pro_republic));
    Q.nationalism = Math.max(0, Math.min(100, Q.nationalism));
}

