function e2_months_until(y, m) { return (y - Q.year) * 12 + (m - Q.month); }
if (Q.president == "Hindenburg" && !Q.hindenburg_dead) {
    Q.e2_next_presidential_time = Q.time + Math.max(1, e2_months_until(1934, 8));
    Q.e2_next_presidential_year = Q.year < 1934 || (Q.year == 1934 && Q.month < 8) ? 1934 : Q.year;
} else if (String(Q.president || "").indexOf("(acting)") >= 0) {
    // An acting President inherited from Era I is replaced at the next opportunity.
    Q.e2_next_presidential_time = Q.time + 3;
    Q.e2_next_presidential_year = Q.month <= 9 ? Q.year : Q.year + 1;
} else {
    Q.e2_next_presidential_time = Q.time + e2_months_until(1941, 4);
